Tool response:
Tool: create_auction
Description: Create Auction
Parameters:
    {
      "type": "object",
      "properties": {
        "title": {
          "type": "string",
          "title": "Title"
        },
        "start_time": {
          "type": "string",
          "title": "Start Time"
        },
        "end_time": {
          "type": "string",
          "title": "End Time"
        },
        "buyer_premium_percent": {
          "type": "number",
          "title": "Buyer Premium Percent"
        },
        "bid_increment": {
          "type": "number",
          "title": "Bid Increment"
        }
      },
      "required": [
        "title",
        "start_time",
        "end_time",
        "buyer_premium_percent",
        "bid_increment"
      ]
    }

Tool response:
Tool: create_lot
Description: Create Lot
Parameters:
    {
      "type": "object",
      "properties": {
        "auction_id": {
          "type": "integer",
          "title": "Auction Id"
        },
        "title": {
          "type": "string",
          "title": "Title"
        },
        "artist": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Artist"
        },
        "starting_bid": {
          "type": "number",
          "title": "Starting Bid"
        },
        "reserve_price": {
          "anyOf": [
            {
              "type": "number"
            },
            {
              "type": "null"
            }
          ],
          "title": "Reserve Price"
        }
      },
      "required": [
        "auction_id",
        "title",
        "starting_bid"
      ]
    }

Tool response:
Tool: upload_lot_document
Description: Upload Lot Document
Parameters:
    {
      "type": "object",
      "properties": {
        "lot_id": {
          "type": "integer",
          "title": "Lot Id"
        },
        "document_type": {
          "type": "string",
          "enum": [
            "provenance",
            "condition_report"
          ],
          "title": "Document Type"
        },
        "file_name": {
          "type": "string",
          "title": "File Name"
        },
        "file_content": {
          "type": "string",
          "title": "File Content"
        }
      },
      "required": [
        "lot_id",
        "document_type",
        "file_name",
        "file_content"
      ]
    }
